import{_ as a,H as l,f as t,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"09 | 监控概论（上）：有哪些方法可以指导监控数据采集？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Google 的四个黄金指标","slug":"google-的四个黄金指标","link":"#google-的四个黄金指标","children":[]},{"level":2,"title":"RED 方法","slug":"red-方法","link":"#red-方法","children":[]},{"level":2,"title":"USE 方法","slug":"use-方法","link":"#use-方法","children":[]},{"level":2,"title":"监控分类","slug":"监控分类","link":"#监控分类","children":[{"level":3,"title":"业务监控","slug":"业务监控","link":"#业务监控","children":[]},{"level":3,"title":"应用监控","slug":"应用监控","link":"#应用监控","children":[]},{"level":3,"title":"组件监控","slug":"组件监控","link":"#组件监控","children":[]},{"level":3,"title":"资源监控","slug":"资源监控","link":"#资源监控","children":[]},{"level":3,"title":"设备监控","slug":"设备监控","link":"#设备监控","children":[]},{"level":3,"title":"网络监控","slug":"网络监控","link":"#网络监控","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"运维监控系统实战笔记/09｜监控概论（上）：有哪些方法可以指导监控数据采集？.md","filePath":"运维监控系统实战笔记/09｜监控概论（上）：有哪些方法可以指导监控数据采集？.md","lastUpdated":1795561216000}'),r={name:"运维监控系统实战笔记/09｜监控概论（上）：有哪些方法可以指导监控数据采集？.md"};function o(n,e,p,s,E,h){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_09-监控概论-上-有哪些方法可以指导监控数据采集" tabindex="-1">09 | 监控概论（上）：有哪些方法可以指导监控数据采集？ <a class="header-anchor" href="#_09-监控概论-上-有哪些方法可以指导监控数据采集" aria-label="Permalink to &quot;09 | 监控概论（上）：有哪些方法可以指导监控数据采集？&quot;">​</a></h1><p>你好，我是秦晓辉。</p><p>前面几讲我们介绍了监控的一些原理和搭建方法，这一讲开始，我们进入监控实战部分，看看具体怎么监控不同类型的目标对象。我会先用两讲的时间讲一下监控方法论和典型的监控数据采集原理。</p><p>这一讲我们主要介绍监控方法论，因为要监控的目标五花八门，怎样才能让监控数据更加完备，怎样才能知道哪些指标更加重要，解决这些问题都需要监控方法论的指导。目前业界比较流行的方法论有 Google 的四个黄金指标、RED 方法、USE 方法，下面我们一一介绍一下。</p><h2 id="google-的四个黄金指标" tabindex="-1">Google 的四个黄金指标 <a class="header-anchor" href="#google-的四个黄金指标" aria-label="Permalink to &quot;Google 的四个黄金指标&quot;">​</a></h2><p>Google 的四个黄金指标着眼点在服务监控，这四个指标分别是延迟、流量、错误和饱和度。</p><ul><li><p>延迟：服务请求所花费的时间，比如用户获取商品列表页面调用的某个接口，花费 30 毫秒。这个指标需要区分成功请求和失败请求，因为失败的请求可能会立刻返回，延迟很小，会扰乱正常的请求延迟数据。</p></li><li><p>流量：HTTP 服务的话就是每秒 HTTP 请求数，RPC 服务的话就是每秒 RPCCall 的数量，如果是数据库，可能用数据库系统的事务量来作为流量指标。</p></li><li><p>错误：请求失败的速率，即每秒有多少请求失败，比如 HTTP 请求返回了 500 错误码，说明这个请求是失败的，或者虽然返回的状态码是 200，但是返回的内容不符合预期，也认为是请求失败。</p></li><li><p>饱和度：描述应用程序有多“满”，或者描述受限的资源，比如 CPU 密集型应用，CPU 使用率就可以作为饱和度指标。</p></li></ul><p>有了这个方法论的指导，我们就知道服务监控应该重点关注哪些指标了。如果要为某个服务配置监控大盘，监控大盘里就要包含上述这几类指标。如果要配置告警规则，也要重点照顾这几类指标。</p><p>可以这么说，只要上述这些指标都是正常的，这个服务就是健康的。反之，如果这些指标有问题，服务就是不健康的，并且大概率已经影响了上游服务甚至终端用户。</p><p>Google 的四个黄金指标主要是针对服务的监控，Weaveworks 的工程师认为饱和度这个指标比较高级，延迟、流量、错误这三个指标相对更重要，所以将其简化为 RED 方法，下面我们来看一下 RED 方法的定义。</p><h2 id="red-方法" tabindex="-1">RED 方法 <a class="header-anchor" href="#red-方法" aria-label="Permalink to &quot;RED 方法&quot;">​</a></h2><ul><li><p>（Request）Rate：请求速率，每秒请求数。</p></li><li><p>（Request）Errors：错误，每秒错误请求数。</p></li><li><p>（Request）Duration：延迟，每个请求的延迟分布情况。</p></li></ul><p>三个英文单词取首字母组成 RED 方法，姑且可以看做是 Google 四个黄金指标的简化版，作者很逗，说为什么起名为 RED 呢？因为他们内部普遍应用 USE 方法，为了和 USE 相呼应，所以取了 RED 这个自认为响亮的名字。这个 USE 又是什么方法呢？下面我们就来介绍一下。</p><h2 id="use-方法" tabindex="-1">USE 方法 <a class="header-anchor" href="#use-方法" aria-label="Permalink to &quot;USE 方法&quot;">​</a></h2><p>USE 方法的提出者是大名鼎鼎的 Brendan Gregg，如果你没听过这个名字，也没关系，你应该听过火焰图吧，性能分析用的火焰图就是这位大哥发明的。你可以点开 USE 方法的官方介绍看看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/1.png" alt=""></a></p><ul><li>火焰图（图片源自网络）</li></ul><p>USE 是使用率（Utilization）、饱和度（Saturation）、错误（Error）的缩写，主要用于分析资源问题。什么是资源？在 Gregg 对模型的定义中，是指传统意义上的物理服务器组件，比如CPU、硬盘等，但现在很多人已经扩展了资源的范围，把一些软件资源也包含在内。下面我们对使用率、饱和度、错误做一个更详细的解释。</p><ul><li><p>使用率：这个我们最熟悉，比如内存使用率、CPU 使用率等，是一个百分比。</p></li><li><p>饱和度：资源排队工作的指标，无法再处理额外的工作。通常用队列长度表示，比如在iostat 里看到的 aqu-sz 就是队列长度。</p></li><li><p>错误：资源错误事件的计数。比如 malloc() 失败次数、通过 ifconfig 看到的 errors、dropped 包量。有很多错误是以系统错误日志的方式暴露的，没法直接拿到某个统计指标，此时可以进行日志关键字监控。</p></li></ul><p>USE 方法和 Google 四个黄金指标配合使用，我们就可以知道不同类别的监控对象应该关注的核心指标是什么了。那监控对象都有哪些类别呢？换句话说，我们做了哪些方面的监控才算是把监控体系建设完备了？下面我们就来梳理一下监控对象的类别。</p><h2 id="监控分类" tabindex="-1">监控分类 <a class="header-anchor" href="#监控分类" aria-label="Permalink to &quot;监控分类&quot;">​</a></h2><p>为了方便你理解，我画了一张图，把监控分成 4 个类别。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/2.png" alt=""></a></p><h3 id="业务监控" tabindex="-1">业务监控 <a class="header-anchor" href="#业务监控" aria-label="Permalink to &quot;业务监控&quot;">​</a></h3><p>这类指标是管理层非常关注的，代表企业营收，或者跟客户主流程相关，类似 BI 数据。不过相比 BI 数据，业务监控指标有两点不同。</p><ul><li><p>对精确度要求没有那么高：因为监控只要发现趋势异常就可以，至于是从 5000 变成了1000 还是变成了 1001，没有什么区别。</p></li><li><p>对实时性要求很高：很多 BI 数据可能是小时级别或天级别的，这个时效性无法满足监控的需求，监控是希望越早发现问题越好，要是一个小时才发现问题，黄花菜都凉了。</p></li></ul><p>技术人员应该针对这类指标做高优保障，如果所有的指标都同等对待，重要的告警就容易被普通告警淹没，所以告警一定要分级对待。</p><p>很多公司的故障管理比较粗放，只要有报警事件产生，就认为是有故障，这是不对的。在微服务和云原生技术盛行的当下，某个机器的 CPU 飙高了，或者 IO 打满了，对最终用户的体验可能是没有任何影响的，但是核心业务指标异常，一定是故障，因为这类指标异常代表着最终用户体验受损，或者造成了直接资损。</p><p>作为中后台的团队，做的很多稳定性保障的工作不容易让管理层看到，业务指标是一个突破口，如果能够把这类指标梳理清楚，是很容易让老板看到我们的价值的。</p><h3 id="应用监控" tabindex="-1">应用监控 <a class="header-anchor" href="#应用监控" aria-label="Permalink to &quot;应用监控&quot;">​</a></h3><p>应用监控就是指对应用程序（Application）的监控，Google 的四个黄金指标、RED 方法主要就是针对应用监控的。</p><p>每个公司都应该有统一的 APM（Application Performance Management），也就是应用性能管理方案，从指标着手的话一般使用埋点机制来做，比如 StatsD、Prometheus SDK 等，或者直接分析接入层日志，从日志提取指标；从链路追踪着手的话可以使用 Zipkin、SkyWalking等。</p><p>像 Java 这种字节码技术的语言，采用 JavaAgent 技术可以做到代码无侵入埋点。但是像Go、C++ 这类语言，一般都是采用埋点机制来做，由统一的工具团队提供一些框架，在框架里内置埋点逻辑，这样普通研发人员也就基本不会有代码侵入的感觉了。</p><h3 id="组件监控" tabindex="-1">组件监控 <a class="header-anchor" href="#组件监控" aria-label="Permalink to &quot;组件监控&quot;">​</a></h3><p>这里我们把各类数据库、中间件、云平台，统称为组件，组件监控是非常考验知识广度的。一般监控系统的研发人员，很难把每个组件的机理都搞清楚，所以定义统一的接入数据规范，让专业的人去采集各个组件的数据是更合理的做法。</p><p>有个好现象是，很多组件的研发人员，已经开始让组件自身直接支持 Prometheus 协议，吐出metrics 数据，除了 etcd、Kubernetes 这些云原生时代的组件，一些老的组件，比如RabbitMQ、ZooKeeper 等，也在新版本里直接做了支持，实属行业幸事。</p><h3 id="资源监控" tabindex="-1">资源监控 <a class="header-anchor" href="#资源监控" aria-label="Permalink to &quot;资源监控&quot;">​</a></h3><p>基础资源的监控，主要是针对设备和网络，设备又分为服务器、网络设备，网络监控又分为连通性监控、质量监控、流量监控。下面我们分别做个简单介绍。</p><h3 id="设备监控" tabindex="-1">设备监控 <a class="header-anchor" href="#设备监控" aria-label="Permalink to &quot;设备监控&quot;">​</a></h3><p>一提起设备监控，你可能立马会想到 CPU、内存使用率监控，除了这些之外，如果我们想获取硬件模块的健康状况，比如电源电压、风扇转速、主板环境温度等，就需要走 IPMI 协议，通过带外网络采集。</p><p>网络设备，典型的就是交换机、防火墙，一般是通过 SNMP 协议获取指标，比如交换机各个网口的流量、包量。也可以通过 syslog 的方式，把交换机的日志转存出来，到服务器上分析。</p><h3 id="网络监控" tabindex="-1">网络监控 <a class="header-anchor" href="#网络监控" aria-label="Permalink to &quot;网络监控&quot;">​</a></h3><p>网络连通性监控最为常见，通过 ICMP 协议，部署探针机器，对目标设备做 PING 探测，能探通就表示能连通，探测失败就是连不通。当然，有些机器可能是禁 PING 的，此时就需要用TCP 或 HTTP 之类的协议去探测了。</p><p>PING 探测可以拿到丢包率和延迟数据，我们可以用这些数据分析网络质量。比如两个机房之间的专线，我们用 A 机房的探针去探测 B 机房的目的设备，就能轻易知道机房之间的网络质量情况。</p><p>最后是流量监控，也会用在多个地方，比如机器的网卡流量、交换机的网口流量、机房出口流量，也是整个监控体系的重要一环。</p><p>到这里，监控的分类我们就介绍完了，你可以看一下自己公司的监控数据，查漏补缺。上面的分类主要是针对服务端的监控，还有一个大类是端监控，比如 iOS 应用，我们会关注是否卡顿、有没有崩溃、白屏之类的，这算是另一个领域，这里就不展开介绍了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>我们这一讲关注的是监控方法论，因为监控对象很多，监控指标也很多，哪些指标比较重要就需要有一个指导性理论。从大类上来看，分为针对服务的 Google 四个黄金指标和 RED 方法，以及针对资源的 USE 方法。这些方法可以解答哪些指标更为重要这个问题。</p><p>对于监控覆盖完备性问题，我总结了一个监控分类图，共有业务、应用、组件、资源四个大类，当然还有端监控，如果这些类别的监控都建立起来了，监控体系就是相对完备的。</p><p>最后，我把这一讲的内容整理成了一张脑图，方便你理解记忆。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/09/3.png" alt=""></a></p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>“因为监控数据不完备，导致线上环境出了问题却没有发现”这个情况时有发生。比如机器进程总数没有监控、nf_conntrack:table full 没有监控、ulimit 没有监控、MySQL 允许的最大连接数没有监控等等。你可以把你遇到的情况也来留言分享一下，这个信息库非常有价值，也欢迎你把今天的内容分享给你身边的朋友，邀他一起学习。我们下一讲再见！</p>',53)])])}const g=a(r,[["render",o]]);export{c as __pageData,g as default};
